{\it $E(z,\bar{z})$ has the following
expansion:
\begin{equation}
E(z,\bar{z})=\sum_{\{i_k \cdot j_k=0,\ k=1\cdots,n\}}
E_{(I,J)}(u,v_2,\cdots,v_n)z^I{\overline{z}}^J
            =\sum_{\{i_k \cdot j_k=0,\ k=1,\cdots, n\}}
E_{(I,J)}^{(K)}z^I{\overline{z}}^Ju^{k_1}{v_2}^{k_2}\cdots
{v_n}^{k_n}. \label{2.5}
\end{equation}
Here and in what follows, we  write $I=(i_1,\cdots,i_n)$,
$J=(j_1,\cdots,j_n)$, $K=(k_1,\cdots,k_n)$, $z^I=z_1^{i_1}\cdots
z_n^{i_n}$ and ${\overline{z}}^J=\-z_1^{j_1}\cdots \-z_n^{j_n}$.
Moreover, the coefficients $E_{(I,J)}^{(K)}$ are uniquely determined
by $E$.}

\hspace{0.2cm} {\it There exits a unique formal
transformation of the form in (\ref{2.2}) with the  normalization
\begin{equation}
\begin{cases} f_{i,(0)}(u)=0, \ 1\le i\le n;\\
f_{i,(e_j)}(u)=0\ \mbox{for} \ 1\leq j<i\leq
n;\\
\ f_{1,(e_1)}(u)=0,\
\hbox{Im}\left(f_{i,(e_i)}(u)\right)=0\ \mbox{for} \ 2\leq i \leq n,
 \end{cases}
 \label{2.6}
\end{equation}
 that transforms M  to a formal submanifold defined in the following
 pseudo-normal form:
\begin{equation}
w'=|z'|^2+\varphi(z',\overline{z'}). \label{2.7}
\end{equation}
Here $\varphi=O(|z'|^3)$ and  in the following unique expansion of
$\varphi$,

We need to prove that the following
equation, with unknowns in $(f,g,\ \varphi)$, can be uniquely solved
under the normalization conditions in (\ref{2.6}) and (\ref{2.8}):
\begin{equation}
\begin{array}{l}
w+g(z,w)=\sum\limits_{i=1}^{n}\big(z_i+f_i(z,w)\big)\left(\bar{z_i}+\overline{f_i(z,w)}\right)
       +\varphi\left(z+f(z,w),\overline{z}+\overline{f(z,w)}\right).
\end{array}
\end{equation}

 Collecting terms of degree $t$
in the above equation, we obtain for each $t
\geq 3$ the following:
\begin{equation}
\begin{array}{ll}
E^{(t)}(z,\bar{z})+g^{(t)}(z,u)
=2Re\sum\limits_{i=1}^{n}\Big(\overline{z_i}f_i^{(t-1)}(z,u)\Big)
+\varphi^{(t)}(z,\bar{z})+I^{(t)}(z,\bar{z}), \label{hu-02}
\end{array}
\end{equation}
where $I^{(t)}(z,\bar{z})$ is a homogeneous polynomial of degree $t$
depending only on $g^{(\sigma)}$, $f^{(\sigma-1)}$,
$\varphi^{(\sigma)}$ for $\sigma < t$. Thus, by an induction
argument,  we need only to uniquely  solve the following  equation
under the above given normalization:
\begin{equation}
\Gamma(z,\bar{z})+g(z,u)=2Re\left(\sum\limits_{i=1}^{n}\left(\overline{z_i}f_i(z,u)\right)\right)+
\varphi(z,\bar{z}). \label{2.9}
\end{equation}
Indeed, if we can uniquely solve (\ref{2.9}), then, we can start with (\ref{hu-02}) with $t=3$ and $\Gamma=E^{(3)}$. We then get $(F^{(2)}, G^{(3)}).$
Now, we transform $M$ by $H_2=(z,w)+(F^{(2)}, G^{(3)})$. Then the new manifold is normalized up to weighted order $3$. Let $H=(F,G)=(z+O_{wt}(3),w+O_{wt}(4))$
be a normalized map and

 consider (\ref{hu-02}) with $t=4$. We can then uniquely determine $(F^{(3)},G^{(4)})$.
 Transforming the manifold by the map
  $H_2=(z,w)+(F^{(3)}, G^{(4)})$, we get  one which is normalized up to order $4$. Now, by an induction, we can prove the existence part of
 Theorem 2.3. The uniqueness part of the Theorem follows also from the unique solvability of (\ref{2.9}).

Expand $\Gamma$, $\varphi$ as in (\ref{2.5}) and (\ref{2.80}) and
expand $f$, $g$ as in  (\ref{2.4}). Making use of Lemma 2.2 and
comparing the coefficients in (\ref{2.9}) of $z^I\-{z}^J$ with
$i_l\cdot j_l=0, \ l=1,\cdots, n$, we get the following system:


\begin{align}
z^0\-{z}^0:&\ \ \ -g_{(0)}+\sum\limits_{i=1}^{n}2Re\left(|z_i|^2f_{i,(e_i)}\right)+\varphi_{(0,0)}=\Gamma_{(0,0)};\label{3.2.10}\\
z_j,\ \-{z_j}:&\ \ \ \begin{cases}
   -g_{(e_j)}+\overline{f_{j,(0)}}+\sum\limits_{i=1}^{n}|z_i|^2f_{i,(e_i+e_j)}+\varphi_{(e_j,0)}=\Gamma_{(e_j,0)}\\
   f_{j,(0)}+\sum\limits_{i=1}^{n}|z_i|^2\overline{f_{i,(e_i+e_j)}}+\varphi_{(0,e_j)}=\Gamma_{(0,e_j)}
      \end{cases}
            \hskip5pt \mbox{for}\ 1\leq j\leq n;\label{3.2.11}\\
z_i\-{z_j}:&\ \ \  \begin{cases}
   f_{j,(e_i)}+\overline{f_{i,(e_j)}}+\varphi_{(e_i,e_j)}=\Gamma_{(e_i,e_j)}\\
   \overline{f_{j,(e_i)}}+f_{i,(e_j)}+\varphi_{(e_j,e_i)}=\Gamma_{(e_j,e_i)}
   \end{cases} \hskip5pt \mbox{for}\ i\neq j;\label{3.2.12}\\
z_i\-{z}^J,\ z^J\-{z_i}:&\ \ \  \begin{cases}
    \overline{f_{i,(J)}}+\varphi_{(e_i,J)}=\Gamma_{(e_i,J)}\\
    f_{i,(J)}+\varphi_{(J,e_i)}=\Gamma_{(J,e_i)}
    \end{cases}
    \hskip5pt \mbox{for}\ |J|\geq 2,j_i=0;\label{3.2.13}\\
z^I,\ \-{z}^I:&\ \ \  \begin{cases}
    -g_{(I)}+\sum\limits_{i=1}^{n}\left(|z_i|^2f_{i,(I+e_i)}\right)+\varphi_{(I,0)}=\Gamma_{(I,0)}\\
    \sum\limits_{i=1}^{n}\left(|z_i|^2\overline{f_{i,(I+e_i)}}\right)+\varphi_{(0,I)}=\Gamma_{(0,I)}
    \end{cases}
    \hskip5pt \mbox{for}\ |I|\geq 2; \label{3.2.14} \\





z^I\-{z}^J:&\ \ \ \varphi_{(I,J)}=\Gamma_{(I,J)} \ \hbox{for}\ |I|,
|J|\ge 2,\ i_l \cdot j_l=0,\ l=1,\cdots,n. \label{3.2.15}
\end{align}


Here we demonstrate in details  how  the system (\ref{3.2.14}) is uniquely solved. The
others are done similarly  (and, in fact,  more easily). We first
substitute (\ref{2.3}) to (\ref{3.2.14}) and then  collect
coefficients of the zeroth order term, linear terms and higher order terms  in $ v_2,\cdots,v_n$, respectively, while taking  u as a parameter. We
obtain, by Lemma 2.2, the following:

\begin{align}
&\sum_{k}\Gamma_{(I,0)}^{(ke_1)}u^k=-g_{(I)}(u)+2^{1-n}uf_{1,(I+e_1)}+\sum_{i=2}^{n}2^{i-1-n}uf_{i,(I+e_i)}+\sum_{k}\varphi_{(I,0)}^{(ke_1)}u^k;
\label{3.2.17}\\
&\sum_{k}\Gamma_{(I,0)}^{(ke_1+e_j)}u^k=2^{1-j}f_{1,(I+e_1)}+\sum_{i=2}^{j-1}2^{i-1-j}f_{i,(I+e_i)}-2^{-1}f_{j,(I+e_j)}+\sum_{k}\varphi_{(I,0)}^{(ke_1+e_j)}u^k,
\ j\ge 2;\label{3.2.18}\\
 &
\varphi_{(I,0)}^{(k_1e_1+k_2e_2+\cdots+k_ne_n)}=\Gamma_{(I,0)}^{(k_1e_1+k_2e_2+\cdots+k_ne_n)},
k_2+\cdots +k_n\ge 2; \label{3.2.180}
\end{align}
\begin{align}
&\sum_{k}\Gamma_{(0,I)}^{(ke_1)}u^k=2^{1-n}u\overline{f_{1,(I+e_1)}}+\sum_{i=2}^{n}2^{i-1-n}u\overline{f_{i,(I+e_i)}}
+\sum_{k}\varphi_{(0,I)}^{(ke_1)}u^k;\label{3.2.19}\\


&\sum_{k}\Gamma_{(0,I)}^{(ke_1+e_j)}u^k=2^{1-j}\overline{f_{1,(I+e_1)}}+\sum_{i=2}^{j-1}2^{i-1-j}\overline{f_{i,(I+e_i)}}-2^{-1}\overline{f_{j,(I+e_j)}}
+\sum_{k}\varphi_{(0,I)}^{(ke_1+e_j)}u^k,\ j\ge 2;\  \label{3.2.20}\\
&
\varphi_{(0,I)}^{(k_1e_1+k_2e_2+\cdots+k_ne_n)}=\Gamma_{(0,I)}^{(k_1e_1+k_2e_2+\cdots+k_ne_n)},\
k_2+\cdots +k_n\ge 2. \label{3.2.200}
\end{align}

Using the normalization in $\varphi$ and letting $u=0$ in (\ref{3.2.17}) (\ref{3.2.19}), we get
$\Gamma^{(0)}_{(I,0)}=-g_{(I)}(0)+\varphi^{(0)}_{(I,0)}$ and
$\Gamma^{(0)}_{(0,I)}=\varphi^{(0)}_{(0,I)}$. By the normalization
$\varphi^{(0)}_{(I,0)}=\-{\varphi^{(0)}_{(0,I)}}$, we get
$\varphi^{(0)}_{(I,0)}=\-{\Gamma^{(0)}_{(I,0)}}$ and
\begin{align}
g_{(I)}(0)=\-{\Gamma^{(0)}_{(0,I)}}-\Gamma^{(0)}_{(I,0)}.
\end{align}

Sum  up (\ref{3.2.20}) with $j=2,\cdots,n$ and then add it to
(\ref{3.2.19}). By the   the normaliztaion condition
$\varphi_{(0,I)}^{(le_1)}=\varphi_{(I,0)}^{(ke_+e_j)}=0$ for $k\ge 0,
l\ge 1$, we obtain the following:
\begin{align}
f_{1,(I+e_1)}(u)=\sum_{k\ge
1}\-{\Gamma_{(0,I)}^{(ke_1)}}u^{k-1}+\sum_{k\ge
0}\sum_{j=2}^{n}\-{\Gamma_{(0,I)}^{(ke_1+e_j)}}u^k.
\end{align}



Subtracting the complex conjugate of (\ref{3.2.20}) from (\ref{3.2.18}), we obtain
\begin{align}
\varphi_{(I,0)}^{(ke_1+e_j)}=\Gamma_{(I,0)}^{(ke_1+e_j)}-\-{\Gamma_{(0,I)}^{(ke_1+e_j)}},\ j\ge 2,\ k\ge 0.
\end{align}
From (\ref{3.2.17}) and (\ref{3.2.20}), we can similarly get
\begin{align}
g_{(I)}(u)=\sum_{k=0}^{\infty}\left(\-{\Gamma_{(0,I)}^{(ke_1)}}-\Gamma_{(I,0)}^{(ke_1)}\right)
u^k,\ \ |I|\ge 2.
\end{align}

Back to the equation (\ref{3.2.20}), we can inductively get:
\begin{align}
f_{j,(I+e_j)}(u)= \sum_{k\ge
1}\overline{\Gamma_{(0,I)}^{(ke_1)}}u^{k-1}+\sum_{k\ge
0}\left(\sum_{i=0}^{n-j-1}\overline{\Gamma_{(0,I)}^{(ke_1+e_{n-i)}}}-
\overline{\Gamma_{(0,I)}^{(ke_1+e_{j})}}\right)u^k\ \mbox{for}\
2\leq j\leq n.
\end{align}








Similarly, we get from (\ref{3.2.10}) the following
\begin{align}
&g_{(0)}(u)=\sum_{k\ge 2}\left(-\Gamma_{(0,0)}^{(ke_1)}u^k\right)-Re
  \left(\sum_{k\ge 1;\ j=2,\cdots,n}
  \Gamma_{(0,0)}^{(ke_1+e_j)}u^{k+1}\right);\\
& f_{h,(e_h)}(u)=\frac{1}{2}\sum_{k\ge 1}\left(-\sum_{j=2}^{h-1}Re(
  \Gamma_{(0,0)}^{(ke_1+e_j)}u^k)-2Re (
  \Gamma_{(0,0)}^{(ke_1+e_h)}u^k)\right), \ h\ge 2;\\


&\varphi_{(0,0)}=\Gamma_{(0,0)}-\sum\limits_{k\geq
2}\Gamma_{(0,0)}^{(ke_1)}u^k-Re(\sum\limits_{k\geq
1,j=2,\cdots,n}\Gamma_{(0,0)}^{(ke_1+e_j)}u^kv_j).
\end{align}
From (\ref{3.2.11}), we obtain the following:
\begin{align}
& f_{1,(e_1+e_j)}(u)=\sum_{k\ge
1}\-{\Gamma_{(0,e_j)}^{(ke_1)}}u^{k-1}+\sum_{k\ge
0}\sum_{i=2}^{n}\-{\Gamma_{(0,e_j)}^{(ke_1+e_i)}}u^k;
\\
&f_{i,(e_j+e_i)}(u)= \sum_{k\ge
1}\overline{\Gamma_{(0,e_j)}^{(ke_1)}}u^{k-1}+\sum_{k\ge
0}\left(\sum_{l=0}^{n-i-1}\overline{\Gamma_{(0,e_j)}^{(ke_1+e_{n-l)}}}-
\overline{\Gamma_{(0,e_j)}^{(ke_1+e_{i})}}\right)u^k\ \mbox{for}\ 2\leq i\leq n;\\
&g_{(e_j)}(u)=\sum_{k=1}^{\infty}\left(\-{\Gamma_{(0,e_j)}^{(ke_1)}}-\Gamma_{(e_j,0)}^{(ke_1)}\right) u^k;\\
&\varphi_{(e_j,0)}^{(ke_1+e_l)}=\Gamma_{(e_j,0)}^{(ke_1+e_l)}-\-{\Gamma_{(0,e_j)}^{(ke_1+e_l)}},\ l\ge 2,\ k\ge 0;\\
&\varphi_{(e_j,0)}^{(k_1e_1+k_2e_2+\cdots+k_ne_n)}=\Gamma_{(e_j,0)}^{(k_1e_1+k_2e_2+\cdots+k_ne_n)},
\ k_2+\cdots +k_n\ge 2;\\
&\varphi_{(0,e_j)}^{(k_1e_1+k_2e_2+\cdots+k_ne_n)}=\Gamma_{(0,e_j)}^{(k_1e_1+k_2e_2+\cdots+k_ne_n)},
\ k_2+\cdots +k_n\ge 2.
\end{align}
From (\ref{3.2.12}), we get
\begin{align}


&f_{i,(e_j)}(u)=\sum_{k=1}^{\infty}{\Gamma_{(e_j,e_i)}^{(ke_1)}}u^k, \ i<j;\\
&\varphi^{ke_1}_{(e_i,e_j)}=\Gamma^{(ke_1)}_{(e_i,e_j)}-\-{\Gamma^{(ke_1)}_{(e_j,e_i)}}, \ i<j,\ k\geq 1;\\
&\varphi_{(e_i,e_j)}^{(k_1e_1+k_2e_2+\cdots+k_ne_n)}=\Gamma_{(e_i,e_j)}^{(k_1e_1+k_2e_2+\cdots+k_ne_n)}
,\ \rm{for} \ k_2+\cdots+k_n\geq 1.
\end{align}
From (\ref{3.2.13}), we obtain
\begin{align}
&f_{i,(J)}(u)=\sum_{k\ge 0}{\Gamma_{(J,e_i)}^{(ke_1)}}u^k,\ \ 1\le i\le n ,\\
&\varphi^{(ke_1)}_{(e_i,J)}=\Gamma_{(e_i,J)}^{(ke_1)}-\-{\Gamma_{(J,e_i)}^{(ke_1)}},\ \ 1\le i\le n ,k\geq0,\\
&\varphi_{(J,e_i)}^{(k_1e_1+k_2e_2+\cdots+k_ne_n)}=\Gamma_{(J,e_i)}^{(k_1e_1+k_2e_2+\cdots+k_ne_n)},\
\rm{for} \ k_2+\cdots+k_n\geq 1,\\
&\varphi_{(e_i,J)}^{(k_1e_1+k_2e_2+\cdots+k_ne_n)}=\Gamma_{(e_i,J)}^{(k_1e_1+k_2e_2+\cdots+k_ne_n)},\
\rm{for} \ k_2+\cdots+k_n\geq 1.
\end{align}
where $|J|\ge 2$ and $j_i=0$.



Summarizing the solutions just obtained,  we have the following
formula: (One can also directly verify that they are indeed the
solutions of (\ref{2.9})

with the
normalization conditions given in (\ref{2.6}) and (\ref{2.8}))



\begin{equation}
\begin{array}{cll}
F_1(z,u)&=&z_1+f_1(z,u)=z_1+\sum\limits_{k\ge 0,j_1=0,|J|\geq 1
  }z^J\Gamma_{(J,e_1)}^{(ke_1)}u^k+\sum\limits_
  {|I|\geq
  1}z^{I+e_1}S^{(1)}_I,\\
F_h(z,u)&=&z_h+f_h(z,u)=z_h+\frac{1}{2}z_h\sum\limits_{k\ge
1}\big(-\sum\limits_{j=2}^{h-1}Re(
  \Gamma_{(0,0)}^{(ke_1+e_j)}u^k)-2Re (
  \Gamma_{(0,0)}^{(ke_1+e_h)}u^k)\big)\\ &&+\sum\limits_{k\ge 1,i>
  h}z_i\Gamma_{(e_i,e_h)}^{(ke_1)}u^k
+\sum\limits_{k\ge 0,j_h=0,|J|\geq
  2}z^J\Gamma_{(J,e_h)}^{(ke_1)}u^k+\sum\limits_{|I|\geq
  1}z^{I+e_h}S^{(h)}_I,\ \ \  n\ge h\geq 2,\\
G(z,u)&=&u+g(z,u)=u+\left(-\sum\limits_{k\ge
2}\Gamma_{(0,0)}^{(ke_1)}u^k-Re (\sum\limits_{k \geq 1,j=2,\cdots,n}
  \Gamma_{(0,0)}^{(ke_1+e_j)}u^{k+1})\right)\\ &&+\sum\limits_{k\ge 0,|I|\geq
  1}z^Iu^k\left(\overline{\Gamma_{(0,I)}^{(ke_1)}}-\Gamma_{(I,0)}^{(ke_1)}
 \right),\\
\varphi&=&\Gamma(z,\bar{z})+g(z,u)-2Re\left(\sum\limits_{i=1}^{n}\left(\overline{z_i}f_i(z,u)\right)\right),





\label{2.10}
\end{array}
\end{equation}
where
\begin{equation}\left\{
\begin{array}{l}
S^{(1)}_I=\sum\limits_{k\ge 1}\overline{\Gamma_{(0,I)}^{(ke_1)}}u^{k-1}+\sum\limits_{k\ge 0}\sum\limits_{i=2}^{n}\overline{\Gamma_{(0,I)}^{(ke_1+e_{i})}}u^{k},\\
S^{(h)}_I=\sum\limits_{k\ge
1}\overline{\Gamma_{(0,I)}^{(ke_1)}}u^{k-1}+\left(\sum\limits_{k\ge
0}\sum\limits_{i=0}^{n-h-1}\overline{\Gamma_{(0,I)}^{(ke_1+e_{n-i)}}}u^{k}\right)-\sum\limits_{k\ge
0} \overline{\Gamma_{(0,I)}^{(ke_1+e_{h})}}u^k,\ \mbox{for}\ 2\leq
h\leq n.
\end{array}
\right. \label{2.11}
\end{equation}


This completes the proof of Theorem 2.3. $\hbox{\vrule height1.5ex width.5em}

\hspace{0.2cm} {\it $Aut_0(M_\infty)$ consists of
 the transformations given in the following (\ref{3.1}) or (\ref{3.2}) :\\
\begin{equation}
 \left\{
\begin{array}{l}
z'=b(w)\frac
          {wa(w)-\frac{\langle z,\bar{a}(w)\rangle}{\langle
                a(w),\bar{a}(w)\rangle}a(w)
                +\sqrt{1-wa(w)\bar{a}(w)}\left(z-\frac{\langle z,\bar{a}(w)\rangle}{\langle a(w),\bar{a}(w)\rangle}a(w)\right)}
          {1-\langle z,\bar{a}(w)\rangle}
  U(w)\\
w'=b(w)\bar{b}(w)w
\end{array}
\right. \label{3.1}
\end{equation}
\begin{equation}
(z',w')=\left(b(w)zU(w),b(w)\bar{b}(w)w\right). \label{3.2}
\end{equation}
where $a=(a_1,\cdots,a_n)$,
$\sum_{j=1}^na_j(0)\bar{a_j}(0)<1$,
 $\langle z,\bar{a} \rangle
=\sum\limits_{i=1}^n\bar{a_i}z_i$, $b(0)\neq 0$, $a(0)\neq 0$,
$U(Re(w))$ is a unitary matrix and $a(w),b(w),U(w)$ are holomorphic
in $w$.}

Making use of (\ref{4.6.0}), we have
\begin{equation}
\begin{array}{l}
E'(z',\-{z'})=\Big(\hat{g}(z,\Phi)-\hat{g}(z,u)\Big)-2Re\Big(\sum\limits_{i=1}^{n}\overline{z_i}(\hat{f}_i(z,\Phi)
   -\hat{f}_i(z,u))\Big)-|\hat{f}(z,\Phi)|^2+\hat\varphi(z,\bar{z}).
\end{array}
\label{4.8}
\end{equation}
Since  $Ord(E)\geq d$, by (\ref{2.10}) and (\ref{2.11}),  we see
that $Ord(\hat{f})\geq d-1$ and $Ord(\hat{g}) \geq d$. Hence, we
have
\begin{equation*}
\begin{array}{l}
Ord\Big(\hat{g}(z,\Phi)-\hat{g}(z,u)\Big) \geq  \min\{(d-1)+d,2d-2\}=2d-2,\\
Ord\Big(\hat{f}_i(z,\Phi)-\hat{f}_i(z,u)\Big) \geq \min\{(d-2)+d,2d-3\}=2d-3,\\
Ord\Big(\left|\hat{f}(z,\Phi)\right|^2\Big) \geq 2(d-1)=2d-2.
\end{array}
\end{equation*}
Thus $Ord(E'-\hat{\varphi}) \geq 2d-2$. By  Lemma 3.3 and the
assumption that $w=|z|^2+E$ is formally equivalent to $w=|z|^2$, we
have $s=\infty$. Hence we have $Ord(\varphi) \geq 2d-2$. The lemma
follows.$\hbox{\vrule height1.5ex width.5em}

\hspace{0.2cm}{\it If $E$ is holomorphic in
$\-{D_r}$, then we have
\begin{equation*}
\begin{array}{l}
|E^{(ke_1)}_{(I,T)}|\leq
\frac{(k+2)^n\|E\|_r}{R^{I+T}\cdot(2r^2)^k}\ ,\
|E^{(ke_1+e_j)}_{(I,T)}| \leq
\frac{2^n(k+2)^n\|E\|_r}{R^{I+T}(2r^2)^{k+1}}.
 \end{array}
\end{equation*}
}

We here give the estimates for
$|E^{(ke_1)}_{(0,I)}|$, $|E^{(ke_1+e_j)}_{(0,I)}|$. The others can
be done similarly. Suppose that $E=\sum a_{i_1\cdots i_nj_1\cdots
j_n}z_1^{i_1} \cdots z_n^{i_n} \overline{z_1}^{j_l}\cdots
\overline{z_1}^{j_l}$. Then by (\ref{2.4}), we have
\begin{equation*}
\begin{array}{lll}
E_{(0,I)}&=&\sum\limits_J a_{j_1\cdots j_n(i_1+j_1)\cdots
(i_n+j_n)}|z_1|^{2j_1}\cdots |z_n|^{2j_n}\\
    &=&\sum\limits_J
    a_{J(I+J)}\left(2^{1-n}(u+\sum\limits_{i=2}^{n}2^{n-i}v_i)\right)^{j_1}
    \Pi_{h=2}^{n}\left(2^{h-n-1}(u+\sum\limits_{i=h+1}^{n}2^{n-i}v_i-v_h)\right)^{j_h}\\
    &=&\sum\limits_J
    a_{J(I+J)}2^{-\left((n-1)j_1+\sum\limits_{h=2}^{n}(n-h+1)j_h\right)}
    \Big(u^{|J|}+\sum\limits_{k=2}^{n}2^{n-k}\left(\sum\limits_{h=1}^{k-1}j_h-j_k\right)u^{|J|-1}v_k\\
    &&\hskip 10pt +O\left(\left|(v_2,\cdots,v_n)\right|^2\right)\Big).\\
\end{array}
\end{equation*}
Thus we obtain
\begin{equation}
\begin{array}{l}
E_{(0,I)}^{(ke_1)}=\sum\limits_{|J|=k}a_{J(I+J)}2^{-\left((n-1)j_1+\sum\limits_{h=2}^{n}(n-h+1)j_h\right)},\\
E_{(0,I)}^{(ke_1+e_l)}=\sum\limits_{|J|=k+1}a_{J(I+J)}2^{-\left((n-1)j_1+\sum\limits_{h=2}^{n}(n-h+1)j_h\right)}2^{n-l}\left(\sum\limits_{h=1}^{l-1}j_h-j_l\right).
\end{array}
\label{4.9}
\end{equation}
By the Cauchy estimates, we get
\begin{equation*}
\begin{array}{lll}
|E_{(0,I)}^{ke_1}|&=&|\sum\limits_{|J|=k}a_{J(I+J)}2^{-\left((n-1)j_1+\sum\limits_{h=2}^{n}(n-h+1)j_h\right)}|\\
     &\leq& \sum\limits_{|J|=k}\frac{\|E\|_r}{R^{I+2J}}2^{-\left((n-1)j_1+\sum\limits_{h=2}^{n}(n-h+1)j_h\right)}\\
     &=& \sum\limits_{|J|=k}\frac{\|E\|_r}{R^{I}}\frac{2^{-\left((n-1)j_1+(n-1)j_2+\cdots+j_n\right)}}
          {(2^{2-n}r^2)^{j_1}\cdot (2^{2-n}r^2)^{j_2} \cdots
          (r^2)^{j_n}}\\
     &\leq& \frac{(k+1)^n\|E\|_r}{R^{I}\cdot(2r^2)^k},\\
|E_{(0,I)}^{ke_1+e_l}|&=&|\sum\limits_{|J|=k+1}a_{J(I+J)}2^{-\left((n-1)j_1+\sum\limits_{h=2}^{n}(n-h+1)j_h\right)}2^{n-l}
\left(\sum\limits_{h=1}^{l-1}j_h-j_l\right)|\\
     &\leq& \sum\limits_{|J|=k+1}\frac{\|E\|_r}{R^{I+2J}}2^{-\left((n-1)j_1+\sum\limits_{h=2}^{n}(n-h+1)j_h\right)}2^{n-l}|\sum\limits_{h=1}^{l-1}j_h-j_l|\\
     &\leq& \sum\limits_{|J|=k+1}\frac{\|E\|_r}{R^{I}\cdot
        (2r^2)^{k+1}}2^n(k+1)\\
     &=&\frac{2^n(k+2)^n\|E\|_r}{R^I\cdot (2r^2)^{k+1}}.
\end{array}
\end{equation*}
Here we have used the fact that
$$
\sharp\left\{(j_1,j_2,\cdots,j_n)\in \mathbb{Z}^n:j_h \geq 0\
\mbox{for}\ 1 \leq h \leq n, \ j_1+j_2+\cdots+j_n=k\right\} \leq
(k+1)^{n-1}.
$$
 This completes the proof of
Lemma 4.2. $\hbox{\vrule height1.5ex width.5em}

\hspace{0.2cm} {\it Let $E,r,\varrho, C(n)$ be
as in Proposition 4.3. Then there exists a constant $\delta>0$ such
that for
\begin{equation}
\frac{C(n)(2d)^{2n}\|E\|_r}{(r-\varrho)^3}(\frac{\varrho}{r})^{\frac{d-1}{2}}
<\delta, \label{4.13}
\end{equation}
$\Psi(z',w'):=\Theta^{-1}(z',w')$ is well defined in
$\-{\triangle_\sigma}$. Moreover, it  holds that
$\Psi(\triangle_{r'}) \subset \triangle_\sigma$,
$\Psi(\triangle_\sigma) \subset \triangle_\varrho$, $E'(z,\xi)$ is
holomorphic in $\-{\triangle_\sigma}$ and
\begin{equation}
\|E'\|_{r'} \leq C_d\|E\|_r^2+\widetilde{C_d}\|E\|_r. \label{4.14}
\end{equation}
Here
\begin{equation*}
\begin{array}{l}
C_d=\frac{(2n+1)\cdot3^3C(n)(2d)^{2n}}{(r-r')^3}(\frac{r'}{r})^{\frac{d-1}{4}}+
(\frac{r'}{r})^{d-1}n\cdot
\left(\frac{3C(n)(2d)^{2n}}{r-r'}\right)^2,\ \
\widetilde{C_d}=\frac{3^{2n}\cdot(2d)^{2n}}{(r-r')^{2n}}(\frac{r'}{r})^{d-1}.
\end{array}
\end{equation*}

We need to show that for each
$(z',w') \in \-{\triangle_{\sigma}}$, we can uniquely solve the
system:
\begin{equation*}
\left\{
\begin{array}{l}
z'=z+\hat{f}(z,w) \\
w'=w+\hat{g}(z,w)
\end{array}
\right.
\end{equation*}
with $(z,w) \in \triangle_{\varrho}$. By (\ref{4.12}), choosing
$\delta$ sufficiently small  such that $|\nabla
\hat{f}|_{\varrho}+|\nabla \hat{g}|_{\varrho}<\frac{1}{2n+4}$ and
$|\hat{f}|_{\varrho}+|\hat{g}|_{\varrho}<\frac{1}{2n+4}.(r-\varrho)$ .
Define $(z^{[1]},w^{[1]})=(z',w') \in \triangle_{\sigma}$ and
$(z^{[j]},w^{[j]})$ inductively by
\begin{equation*}
\left\{
\begin{array}{l}
z^{[j+1]}=z'-\hat{f}(z^{[j]},w^{[j]}) \\
w^{[j+1]}=w'-\hat{g}(z^{[j]},w^{[j]}).
\end{array}
\right.
\end{equation*}

By a standard argument on the Picard iteration procedure, we
can get a unique $(z,w) \in \triangle_{\varrho}$ satisfying
$\Psi^{-1}(z,w)=(z',w')$, which gives that $\Psi(\triangle_\sigma)
\subset \triangle_\varrho$. Similarly, we have $\Psi(\triangle_{r'})
\subset \triangle_\sigma$. Hence we conclude that $E'$ is
holomorphic in $\triangle_\sigma$. Moreover,
\begin{equation}
\|E'\|_{r'} \leq \|Q\|_\sigma
\end{equation}
where
\begin{equation}
\begin{array}{l}
Q=\left(\hat{g}(z,\Phi)-\hat{g}(z,u)\right)-2Re\left(\sum\limits_{i=1}^{n}\overline{z_i}\Large(\hat{f}_i(z,\Phi)-\hat{f}_i(z,u)\Large)\right)
  -|\hat{f}(z,\Phi)|^2
  +\hat{\varphi}(z,\bar{z}).
\end{array}
\label{4.16}
\end{equation}
Notice that
\begin{equation}
\begin{array}{lll}
 |(\hat{g}(z,\Phi)-\hat{g}(z,u)|_{\sigma}
&\leq& |\nabla
  \hat{g}|_{\varrho} \cdot \|E\|_r \leq \frac{C(n)(2d)^{2n}\|E\|_r^2}{(r-\varrho)^3}(\frac{\varrho}{r})^{\frac{d-1}{2}}\\
&\leq&
\frac{3^3C(n)(2d)^{2n}\|E\|_r^2}{(r-r')^3}(\frac{r'}{r})^{\frac{d-1}{4}}.
\end{array}
\label{4.17}
\end{equation}
Here we have used the fact that $(\frac{\varrho}{r})^{2} <
\frac{r'}{r}$. (This can be achieved by the same token as for
(\ref{1.4.13}).)  We also have
\begin{equation}
\begin{array}{l}
|(\hat{f}_i(z,\Phi)-\hat{f}_i(z,u)|_{\sigma} \leq
\frac{3^3C(n)(2d)^{2n}\|E\|_r^2}{(r-r')^3}(\frac{r'}{r})^{\frac{d-1}{4}}\ \rm{for} \ 1\leq i \leq n.\\
|\hat{f}(z,\Phi)|^2_{\sigma} \leq n\cdot \left(\frac{C(n)
{(2d)}^{2n}\|E\|_r}{r-\sigma}(\frac{\sigma}{r})^{d-1}\right)^2 \leq
n \cdot \left(\frac{3C(n)
{(2d)}^{2n}\|E\|_r}{r-r'}\right)^2(\frac{r'}{r})^{d-1}\\
\|\hat{\varphi}\|_{\sigma}\leq
\frac{(2d)^{2n}\|E\|_r}{(r-\sigma)^{2n}}(\frac{\sigma}{r})^{2d-2}
\leq \frac{3^{2n}(2d)^{2n}\|E\|_r}{(r-r')^{2n}}(\frac{r'}{r})^{d-1}.
\end{array}\label{4.18}
\end{equation}
By (\ref{4.16})-(\ref{4.18}), we obtain:
\begin{equation*}
\begin{array}{l}
\|E'\|_{r'} \leq
\left\{\frac{(2n+1)\cdot3^3C(n)(2d)^{2n}}{(r-r')^3}(\frac{r'}{r})^{\frac{d-1}{4}}+
(\frac{r'}{r})^{d-1}n\cdot
\left(\frac{3C(n)(2d)^{2n}}{r-r'}\right)^2\right\}\|E\|_r^2+\frac{3^{2n}\cdot(2d)^{2n}}{(r-r')^{2n}}(\frac{r'}{r})^{d-1}\|E\|_r
\end{array}
\end{equation*}
This completes the proof of Proposition 4.4. $\hbox{\vrule height1.5ex width.5em}
